{"path":"fees.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Investment — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbf8f6;--card:#fff;--muted:#6b6b6b;--accent:#6a8c7f;--accent-2:#8ab4a1;--glass:rgba(255,255,255,0.6)}
    html,body{height:100%;margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;color:#222;background:var(--bg);}
    body{display:flex;flex-direction:column}
    header{background:linear-gradient(180deg,var(--glass),transparent);backdrop-filter:blur(6px);padding:18px 22px;border-bottom:1px solid rgba(0,0,0,0.04)}
    .nav{max-width:980px;margin:0 auto;display:flex;align-items:center;gap:18px}
    .brand{font-weight:700;color:var(--accent)}
    nav a{color:#3a3a3a;text-decoration:none;padding:8px 10px;border-radius:8px}
    nav a[href$="fees.html"]{background:rgba(106,140,127,0.08);color:var(--accent)}
    main{max-width:980px;margin:28px auto;padding:0 22px}
    .hero{display:grid;grid-template-columns:1fr 320px;gap:20px;align-items:start}
    .hero .lead{background:var(--card);padding:22px;border-radius:12px;box-shadow:0 6px 18px rgba(16,24,40,0.06)}
    h1{margin:0 0 8px 0;font-size:22px}
    p.lead{margin:0;color:var(--muted)}
    .aside{background:linear-gradient(180deg,rgba(138,180,161,0.08),transparent);padding:18px;border-radius:12px}
    .price-toggle{display:flex;align-items:center;gap:10px;margin-top:12px}
    .switch{position:relative;width:58px;height:30px;background:#e9efe9;border-radius:999px;cursor:pointer;border:1px solid rgba(0,0,0,0.04)}
    .thumb{position:absolute;top:3px;left:3px;width:24px;height:24px;border-radius:999px;background:white;box-shadow:0 4px 10px rgba(16,24,40,0.08);transition:left .28s cubic-bezier(.2,.9,.3,1)}
    .toggle-labels{font-size:13px;color:var(--muted)}

    .plans{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:18px}
    .plan{background:var(--card);padding:16px;border-radius:12px;border:1px solid rgba(0,0,0,0.04)}
    .plan h3{margin:0 0 6px 0;font-size:16px}
    .amount{font-weight:700;font-size:20px;color:var(--accent)}
    .detail{color:var(--muted);font-size:13px;margin-top:8px}

    .compare-note{font-size:13px;color:var(--muted);margin-top:12px}

    .cta{display:inline-block;margin-top:14px;padding:10px 14px;background:var(--accent);color:#fff;border-radius:10px;text-decoration:none}

    footer{max-width:980px;margin:28px auto;padding:20px 22px;color:var(--muted);font-size:13px}

    /* animated number styles */
    .num{display:inline-block;min-width:80px;text-align:right}

    /* responsive */
    @media (max-width:820px){.hero{grid-template-columns:1fr;}.plans{grid-template-columns:1fr}}

    /* subtle pattern */
    .pattern-bg{background-image:url("assets/img/pattern.svg");background-repeat:repeat;background-size:140px 140px;padding:14px;border-radius:8px}
  </style>
</head>
<body>
  <header>
    <div class="nav">
      <div class="brand">{{BUSINESS_NAME}}</div>
      <nav style="margin-left:18px;display:flex;gap:6px">
        <a href="index.html">Home</a>
        <a href="about.html">Who I Am</a>
        <a href="specialties.html">Areas</a>
        <a href="approach.html">How I Work</a>
        <a href="fees.html">Investment</a>
        <a href="faq.html">FAQ</a>
        <a href="book.html">Book</a>
        <a href="contact.html">Connect</a>
      </nav>
    </div>
  </header>

  <main>
    <section class="hero">
      <div class="lead">
        <h1>Fees & formats that meet where life is right now</h1>
        <p class="lead">Therapy shaped to practical changes—options for one-off focus work, short-term cycles, and ongoing support. Choose what feels manageable; I’ll help keep it confidential and clinically grounded.</p>

        <div class="pattern-bg" style="margin-top:14px">
          <strong>Compare: Monthly vs. Package</strong>
          <div class="price-toggle">
            <div class="toggle-labels">Monthly</div>
            <div id="switch" class="switch" aria-pressed="false" role="switch" tabindex="0">
              <div class="thumb"></div>
            </div>
            <div class="toggle-labels">Package</div>
          </div>

          <div class="plans" style="margin-top:12px">
            <div class="plan">
              <h3>Foundation Session</h3>
              <div class="amount"><span class="num" data-month="130" data-package="115">$130</span><span style="font-weight:400"> / session</span></div>
              <div class="detail">Single sessions for immediate support and planning.</div>
            </div>

            <div class="plan">
              <h3>Momentum Cycle (6)</h3>
              <div class="amount"><span class="num" data-month="120" data-package="95">$120</span><span style="font-weight:400"> / session</span></div>
              <div class="detail">Six-session package designed for focused change work.</div>
            </div>
          </div>

          <div class="plans">
            <div class="plan">
              <h3>Short-Term Focus (3)</h3>
              <div class="amount"><span class="num" data-month="125" data-package="110">$125</span><span style="font-weight:400"> / session</span></div>
              <div class="detail">Three-session block to address a clear problem or decision.</div>
            </div>

            <div class="plan">
              <h3>Ongoing Collaboration</h3>
              <div class="amount"><span class="num" data-month="140" data-package="125">$140</span><span style="font-weight:400"> / session</span></div>
              <div class="detail">Regular sessions for sustained support; scheduling priority included.</div>
            </div>
          </div>

          <div class="compare-note">Prices shown animate to reflect your selected billing rhythm. Packages commonly include scheduling flexibility and brief check-ins between sessions where clinically appropriate.</div>

        </div>

        <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>

      </div>

      <aside class="aside">
        <h3>Payment & logistics</h3>
        <p style="margin:0;color:var(--muted);font-size:14px">I accept straightforward payments via card. I can provide a receipt suitable for insurance submission on request, but I do not guarantee reimbursement. Sliding-scale openings are limited; please ask about current availability.</p>

        <h4 style="margin-top:12px">Note on confidentiality</h4>
        <p style="margin:0;color:var(--muted);font-size:13px">Sessions are confidential within legal and ethical limits. I will discuss privacy, limits of confidentiality, and record-keeping at intake.</p>
      </aside>
    </section>

    <section style="margin-top:18px;background:var(--card);padding:14px;border-radius:12px;border:1px solid rgba(0,0,0,0.04)">
      <h3 style="margin:0 0 8px 0">How the animated pricing works</h3>
      <p style="margin:0;color:var(--muted);font-size:14px">Toggle between monthly and package views to see the per-session amounts update. This helps compare the rhythm and relative value of different formats without hard-selling a specific commitment.</p>
    </section>

  </main>

  <footer>
    <div>Clinical boundaries: I hold a professional scope of practice as a licensed clinician. I do not provide emergency services. If you or someone is in immediate danger, contact local emergency services or crisis lines in {{CITY}}, {{STATE}}.
    </div>
    <div style="margin-top:8px">Contact: {{EMAIL}} • {{PHONE}}</div>
  </footer>

  <script>
    // Pricing comparator behavior: toggle and animate numbers
    (function(){
      const sw = document.getElementById('switch');
      const thumb = sw.querySelector('.thumb');
      let state = false; // false = monthly, true = package
      const nums = Array.from(document.querySelectorAll('.num'));

      function animateNumbers(toPackage){
        nums.forEach(el=>{
          const from = parseFloat(el.textContent.replace(/[^0-9.]/g,'')) || 0;
          const target = parseFloat(el.dataset[toPackage? 'package':'month']);
          const start = performance.now();
          const dur = 420;
          function step(now){
            const t = Math.min(1,(now-start)/dur);
            const ease = (--t)*t*t+1; // easeOutCubic
            const val = Math.round((from + (target - from) * ease) * 1) ;
            el.textContent = '$' + val;
            if(now - start < dur) requestAnimationFrame(step);
            else el.textContent = '$' + target;
          }
          requestAnimationFrame(step);
        });
      }

      function setState(pack){
        state = !!pack;
        if(state){thumb.style.left='31px'; sw.setAttribute('aria-pressed','true');}
        else {thumb.style.left='3px'; sw.setAttribute('aria-pressed','false');}
        animateNumbers(state);
      }

      sw.addEventListener('click',()=> setState(!state));
      sw.addEventListener('keydown',(e)=>{ if(e.key==='Enter' || e.key===' ') { e.preventDefault(); setState(!state);} });

      // init from DOM values
      nums.forEach(el=>{ el.textContent = '$' + el.dataset.month; });
    })();
  </script>
</body>
</html>"} 
{"path":"faq.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>FAQ — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fffdfb;--card:#ffffff;--muted:#6b6b6b;--accent:#6a8c7f}
    body{font-family:Inter,system-ui,Segoe UI,Roboto,Arial;margin:0;background:var(--bg);color:#222}
    header{padding:14px 18px;border-bottom:1px solid rgba(0,0,0,0.04);background:linear-gradient(180deg,rgba(138,180,161,0.03),transparent)}
    .nav{max-width:980px;margin:0 auto;display:flex;align-items:center;gap:18px}
    .brand{font-weight:700;color:var(--accent)}
    nav a{color:#3a3a3a;text-decoration:none;padding:8px 10px;border-radius:8px}
    nav a[href$="faq.html"]{background:rgba(106,140,127,0.08);color:var(--accent)}

    main{max-width:980px;margin:26px auto;padding:0 18px}
    .grid{display:grid;grid-template-columns:2fr 1fr;gap:18px}
    .card{background:var(--card);padding:18px;border-radius:12px;border:1px solid rgba(0,0,0,0.04)}
    h1{margin:0 0 10px 0;font-size:22px}
    .faq-list{margin-top:12px}
    .q{border-top:1px dashed rgba(0,0,0,0.06);padding:12px 0;cursor:pointer}
    .q h4{margin:0;font-size:15px}
    .a{margin-top:8px;color:var(--muted);display:none;font-size:14px}

    .m2m{display:flex;flex-direction:column;gap:10px}
    .mood-btn{padding:10px;border-radius:10px;border:1px solid rgba(0,0,0,0.06);background:#fff;cursor:pointer}
    .mood-btn.active{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#fff;border-color:transparent}
    .rec{margin-top:12px;padding:12px;border-radius:10px;background:linear-gradient(180deg,rgba(106,140,127,0.06),transparent)}

    footer{max-width:980px;margin:20px auto;padding:0 18px;color:var(--muted);font-size:13px}
    @media (max-width:900px){.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div class="nav">
      <div class="brand">{{BUSINESS_NAME}}</div>
      <nav style="margin-left:18px;display:flex;gap:6px">
        <a href="index.html">Home</a>
        <a href="about.html">Who I Am</a>
        <a href="specialties.html">Areas</a>
        <a href="approach.html">How I Work</a>
        <a href="fees.html">Investment</a>
        <a href="faq.html">FAQ</a>
        <a href="book.html">Book</a>
        <a href="contact.html">Connect</a>
      </nav>
    </div>
  </header>

  <main>
    <div class="grid">
      <section class="card">
        <h1>Frequently asked questions</h1>
        <div class="faq-list" id="faq">

          <div class="q">
            <h4>What should I expect at my first session?</h4>
            <div class="a">The first session is a collaborative conversation: we clarify your concerns, background, and what you hope to change. I’ll share information about confidentiality and clinical boundaries, and we’ll agree on next steps together.</div>
          </div>

          <div class="q">
            <h4>Do you accept insurance?</h4>
            <div class="a">I do not bill insurance directly at this time. I can provide a superbill/receipt you may submit to your insurer. Coverage decisions are made by your insurance company; I can’t guarantee reimbursement.</div>
          </div>

          <div class="q">
            <h4>How long are sessions and what is your cancellation policy?</h4>
            <div class="a">Standard sessions are 50 minutes. If you need to cancel, please provide as much notice as possible—usually 48 hours—so the time can be offered to someone else. We’ll cover specifics at intake.</div>
          </div>

          <div class="q">
            <h4>Can I message you between sessions?</h4>
            <div class="a">Brief check-ins and scheduling messages are fine; extended therapeutic work happens in sessions. We’ll set boundaries for between-session contact and review limits to confidentiality.</div>
          </div>

        </div>
      </section>

      <aside class="card">
        <h3>Mood-to-Method — quick guide</h3>
        <p style="margin:6px 0 10px 0;color:var(--muted);font-size:14px">Pick a current state and see a practice style paired with it. This is a gentle way to explore what might help right now—and it updates the suggested next step button below.</p>

        <div class="m2m">
          <button class="mood-btn" data-key="overwhelmed">Overwhelmed</button>
          <button class="mood-btn" data-key="stuck">Stuck</button>
          <button class="mood-btn" data-key="anxious">Anxious Nights</button>
          <button class="mood-btn" data-key="avoid">Avoiding Difficult Talk</button>
        </div>

        <div class="rec" id="recPane">
          <strong id="recTitle">Choose a feeling</strong>
          <div id="recText" style="margin-top:8px;color:var(--muted);font-size:14px">Suggestions and a next-step button will appear here.</div>
          <a id="recCta" href="book.html" style="display:inline-block;margin-top:10px;padding:9px 12px;background:var(--accent);color:#fff;border-radius:8px;text-decoration:none">Plan a focused visit</a>
        </div>
      </aside>
    </div>

  </main>

  <footer>
    <div>Clinical note: I operate within a defined clinical scope. If you are in crisis or danger, please contact local emergency services or your region’s crisis line in {{CITY}}, {{STATE}}.</div>
    <div style="margin-top:8px">For confidentiality details and limits, please see intake materials or ask during our first meeting. Contact: {{EMAIL}}</div>
  </footer>

  <script>
    // Simple accordion for FAQ
    document.querySelectorAll('.q').forEach(item=>{
      item.addEventListener('click',()=>{
        const a = item.querySelector('.a');
        const showing = a.style.display === 'block';
        document.querySelectorAll('.q .a').forEach(x=>x.style.display='none');
        if(!showing) a.style.display='block';
      });
    });

    // Mood-to-Method quick map
    (function(){
      const map = {
        overwhelmed:{title:'Short planning session',text:'A single focused session to sort priorities, reduce immediate overload, and create a simple next-step plan.',cta:'Book a single planning session',url:'book.html?mode=planning'},
        stuck:{title:'Three-session focus',text:'A short block to explore patterns, test small adjustments, and regroup with measurable steps.',cta:'Reserve a three-session block',url:'book.html?mode=short_block'},
        anxious:{title:'Early evening check-in',text:'Targeted sessions to work on sleep strategies and calming tools in-session and between sessions.',cta:'Schedule an evening check-in',url:'book.html?mode=sleep_work'},
        avoid:{title:'Conversation practice',text:'Work on preparation and role-play to make difficult discussions feel more manageable and less draining.',cta:'Start conversation practice',url:'book.html?mode=skills'}
      };
      const buttons = Array.from(document.querySelectorAll('.mood-btn'));
      const recTitle = document.getElementById('recTitle');
      const recText = document.getElementById('recText');
      const recCta = document.getElementById('recCta');

      function setSelection(key,btn){
        buttons.forEach(b=>b.classList.remove('active'));
        if(btn) btn.classList.add('active');
        if(map[key]){
          recTitle.textContent = map[key].title;
          recText.textContent = map[key].text;
          recCta.textContent = map[key].cta;
          recCta.href = map[key].url;
        }
      }

      buttons.forEach(b=>{
        b.addEventListener('click',()=> setSelection(b.dataset.key,b));
      });

    })();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Schedule — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fcfbf8;--accent:#6a8c7f;--muted:#6c6c6c}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial;color:#222;background:var(--bg)}
    header{padding:14px 18px;border-bottom:1px solid rgba(0,0,0,0.04)}
    .nav{max-width:980px;margin:0 auto;display:flex;align-items:center;gap:18px}
    .brand{font-weight:700;color:var(--accent)}
    nav a{color:#3a3a3a;text-decoration:none;padding:8px 10px;border-radius:8px}
    nav a[href$="book.html"]{background:rgba(106,140,127,0.08);color:var(--accent)}

    main{max-width:980px;margin:26px auto;padding:0 18px}
    .grid{display:grid;grid-template-columns:1fr 360px;gap:18px}
    .card{background:#fff;padding:18px;border-radius:12px;border:1px solid rgba(0,0,0,0.04)}
    h1{margin:0 0 6px 0;font-size:22px}
    p.lead{margin:0;color:var(--muted)}

    .mood-grid{display:flex;flex-wrap:wrap;gap:10px;margin-top:12px}
    .mood{flex:1 1 140px;padding:12px;border-radius:10px;border:1px solid rgba(0,0,0,0.06);background:#fff;cursor:pointer;text-align:center}
    .mood.active{background:linear-gradient(90deg,var(--accent),#8ab4a1);color:#fff;border-color:transparent;transform:translateY(-4px)}

    .method{margin-top:16px;padding:12px;border-radius:10px;background:linear-gradient(180deg,rgba(106,140,127,0.06),transparent)}
    .method h3{margin:0}
    .method p{margin:6px 0 0 0;color:var(--muted)}
    .book-cta{display:inline-block;margin-top:12px;padding:10px 14px;background:var(--accent);color:#fff;border-radius:10px;text-decoration:none}

    footer{max-width:980px;margin:20px auto;padding:0 18px;color:var(--muted);font-size:13px}
    @media (max-width:900px){.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div class="nav">
      <div class="brand">{{BUSINESS_NAME}}</div>
      <nav style="margin-left:18px;display:flex;gap:6px">
        <a href="index.html">Home</a>
        <a href="about.html">Who I Am</a>
        <a href="specialties.html">Areas</a>
        <a href="approach.html">How I Work</a>
        <a href="fees.html">Investment</a>
        <a href="faq.html">FAQ</a>
        <a href="book.html">Book</a>
        <a href="contact.html">Connect</a>
      </nav>
    </div>
  </header>

  <main>
    <div class="grid">
      <section class="card">
        <h1>Find the right kind of session today</h1>
        <p class="lead">Choose how you feel. The recommendation adapts, and the action button updates to match what you might need right now.</p>

        <div class="mood-grid" id="moodGrid">
          <div class="mood" data-key="overwhelmed">Overwhelmed</div>
          <div class="mood" data-key="stuck">Stuck</div>
          <div class="mood" data-key="anxious">Anxious Nights</div>
          <div class="mood" data-key="avoid">Avoiding Talk</div>
          <div class="mood" data-key="grief">Grief & Loss</div>
          <div class="mood" data-key="relationship">Relationship Strain</div>
        </div>

        <div class="method" id="methodPane">
          <h3 id="methodTitle">Select a mood</h3>
          <p id="methodText" style="color:var(--muted)">When you choose how you're feeling, I'll suggest a next step and a tailored session type. This is not a diagnosis—just a way to align what happens in session with what matters to you right now.</p>

          <a id="bookBtn" class="book-cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        </div>

        <div style="margin-top:12px;color:var(--muted);font-size:13px">If you’re unsure, select the option that feels closest. We’ll clarify needs together in the first visit.</div>
      </section>

      <aside class="card">
        <h3>Quick logistics</h3>
        <p style="margin:6px 0 0 0;color:var(--muted);font-size:14px">Sessions are available weekday afternoons and some evenings. After you choose a session type, the booking link will take you to the scheduler to pick a time.</p>

        <h4 style="margin-top:12px">Confidentiality & limits</h4>
        <p style="margin:6px 0 0 0;color:var(--muted);font-size:13px">Conversations are confidential except in legal or safety-related exceptions. I will review privacy and record-keeping at intake.</p>

      </aside>
    </div>
  </main>

  <footer>
    <div>Clinical boundaries: I do not provide emergency services. If you are in immediate danger or crisis, contact local emergency services or crisis lines in {{CITY}}, {{STATE}}.</div>
    <div style="margin-top:8px">For questions: {{EMAIL}} • {{PHONE}}</div>
  </footer>

  <script>
    // Mood-to-Method: maps mood to recommended approach and CTA text
    (function(){
      const map = {
        overwhelmed:{title:'Single planning session',text:'A focused 50-minute meeting to reduce immediate load, set priorities, and identify two small next steps.',cta:'Book a planning session',url:'{{PRIMARY_CTA_URL}}?type=planning'},
        stuck:{title:'3-session momentum block',text:'Three sessions over 6–8 weeks to test small changes and build forward momentum.',cta:'Reserve a 3-session block',url:'{{PRIMARY_CTA_URL}}?type=short_block'},
        anxious:{title:'Evening check-in',text:'Short-term sessions to address sleep, worry cycles, and calming practices you can apply between meetings.',cta:'Schedule an evening slot',url:'{{PRIMARY_CTA_URL}}?type=sleep'},
        avoid:{title:'Conversation rehearsal',text:'Workshops in session to practice and prepare for hard conversations—role-play and planning included.',cta:'Start conversation practice',url:'{{PRIMARY_CTA_URL}}?type=skills'},
        grief:{title:'Grief-focused sessions',text:'A supportive space to sit with loss, process feelings, and find stabilizing routines.',cta:'Book grief support',url:'{{PRIMARY_CTA_URL}}?type=grief'},
        relationship:{title:'Couples or individual relational work',text:'Short assessments followed by tailored sessions to build clearer patterns and better connection.',cta:'Schedule relational work',url:'{{PRIMARY_CTA_URL}}?type=relationship'}
      };

      const moodEls = Array.from(document.querySelectorAll('.mood'));
      const titleEl = document.getElementById('methodTitle');
      const textEl = document.getElementById('methodText');
      const bookBtn = document.getElementById('bookBtn');

      function setMood(key,el){
        moodEls.forEach(m=>m.classList.remove('active'));
        if(el) el.classList.add('active');
        const entry = map[key];
        if(entry){
          // morphing animation
          titleEl.style.opacity=0; textEl.style.opacity=0; bookBtn.style.opacity=0;
          setTimeout(()=>{
            titleEl.textContent = entry.title;
            textEl.textContent = entry.text;
            bookBtn.textContent = entry.cta;
            bookBtn.href = entry.url;
            titleEl.style.opacity=1; textEl.style.opacity=1; bookBtn.style.opacity=1;
          },180);
        }
      }

      moodEls.forEach(m=>m.addEventListener('click',()=> setMood(m.dataset.key,m)));

      // check query param to preselect
      const params = new URLSearchParams(location.search);
      const preset = params.get('mode') || params.get('type');
      if(preset){
        // try to match keys loosely
        const key = Object.keys(map).find(k=>preset.includes(k) || preset===k) || null;
        if(key){
          const el = moodEls.find(m=>m.dataset.key===key);
